

sys = tf([0 0 0.5],[1 0.8 1]) %[output:355ce5cb]

[y,t] = step(sys,15) %[output:62539f92] %[output:022105b1]

figure("visible",true) %[output:86bc25ab]
hold on %[output:86bc25ab]
plot(t,y/max(y),'linewidth',1.5) %[output:86bc25ab]
plot(t,t*0+y(end)/max(y),'linewidth',1.5) %[output:86bc25ab]
hold off %[output:86bc25ab]

box off %[output:86bc25ab]
ylim([0,1.2]) %[output:86bc25ab]
